 internal static void RequireVariants(SkirmishMissionLogicalBindingConfig binding,SkirmishScenarioDefinitionConfig definition,JObject context){bool all=SourceDeclaredMissionConfiguration.RequireLayoutSelection(definition.MapLayout,context,definition.CampaignMap);var variants=binding.Variants;if(variants.Any(v=>v==null||v.Areas!=null))throw new InvalidDataException("Complete BA logical variants required");var target=context["target_context"];if(variants.Count(v=>v.Size.ToString()==(string)target["size"]&&v.Difficulty.ToString()==(string)target["difficulty"])!=1)throw new InvalidDataException("One exact selected logical variant required");if(!all&&variants.Length!=1)throw new InvalidDataException("Single declared layout requires one variant");if(all&&(variants.Length!=3||variants.Any(v=>v.Difficulty.ToString()!=(string)target["difficulty"])||variants.Select(v=>v.Size.ToString()).Distinct().Count()!=3||!new[]{"Standard","War","LargeWar"}.All(size=>variants.Any(v=>v.Size.ToString()==size))))throw new InvalidDataException("Measured all-configuration layout requires three size variants for the selected difficulty");}
 internal static void RequireCompiled(JObject descriptor,SkirmishScenarioDefinitionConfig definition,SkirmishResolvedSetup setup,JObject request){
  var root=Read(descriptor,request);var target=root["target_context"];string error=null;
